<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import http from '../../api/http'
import TablePager from '../../shared/components/TablePager.vue'
import { zh } from '../../shared/display'
const rows=ref<any[]>([]),products=ref<any[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),editingId=ref<number|null>(null),keyword=ref(''),status=ref(''),page=ref(1),size=ref(20),total=ref(0)
const form=reactive<any>({operations:[]})
async function load(){loading.value=true;try{const[r,p]=await Promise.all([http.get('/mdm/routings',{params:{keyword:keyword.value||undefined,status:status.value||undefined,page:page.value,size:size.value}}),http.get('/mdm/products/consumable')]);rows.value=r.data.data.content;total.value=r.data.data.totalElements;products.value=p.data.data||[];if(!rows.value.length&&total.value>0&&page.value>1){page.value--;await load()}}finally{loading.value=false}}
function search(){page.value=1;load()}function blankOp(seq=10){return{opSeq:seq,operationCode:'',operationName:'',workCenter:'',setupTimeMin:0,runTimeMin:0,waitTimeMin:0,defaultEquipmentCode:'',requiredSkill:'',keyOperation:false,inspectionOp:false,inspectionRequired:false,remark:''}}
function create(){editingId.value=null;Object.assign(form,{routingCode:'',routingName:'',productCode:'',routingVersion:'V1.0',effectiveDate:new Date().toISOString().slice(0,10),expireDate:'',changeReason:'',operations:[blankOp()]});dialog.value=true}
async function edit(row:any){const{data}=await http.get(`/mdm/routings/${row.id}`);editingId.value=row.id;Object.assign(form,data.data);dialog.value=true}
function addOp(){form.operations.push(blankOp((form.operations.at(-1)?.opSeq||0)+10))}function removeOp(index:number){form.operations.splice(index,1)}
async function save(){if(!form.routingCode||!form.routingName||!form.productCode||!form.operations.length)return ElMessage.warning('请填写路线、产品和至少一道工序');saving.value=true;try{if(editingId.value)await http.put(`/mdm/routings/${editingId.value}`,form);else{await http.post('/mdm/routings',form);page.value=1}ElMessage.success('工艺路线已保存为草稿');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}
async function submit(row:any){try{await http.post(`/mdm/routings/${row.id}/submit`);ElMessage.success('已提交工艺路线审批');await load()}catch(e:any){ElMessage.error(e.message||'提交失败')}}onMounted(load)
</script>
<template><section class="biz-page"><div class="page-head"><div><span>工艺路线管理</span><h1>工艺路线与工序</h1><p>统一维护产品生产版本、工作中心、标准工时、设备与检验工序。</p></div><el-button type="primary" @click="create">新增工艺路线</el-button></div><el-card shadow="never"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="路线编码或名称" @keyup.enter="search"/><el-select v-model="status" clearable placeholder="全部状态" @change="search"><el-option v-for="s in ['DRAFT','PENDING','PUBLISHED','REJECTED','CHANGING']" :key="s" :label="zh(s)" :value="s"/></el-select><el-button @click="search">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="routingCode" label="路线编码"/><el-table-column prop="routingName" label="路线名称" min-width="180"/><el-table-column prop="productCode" label="产品编码"/><el-table-column prop="routingVersion" label="路线版本"/><el-table-column prop="effectiveDate" label="生效日期"/><el-table-column prop="versionNo" label="主版本" width="80"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':row.status==='REJECTED'?'danger':'info'">{{zh(row.status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" :disabled="!['DRAFT','REJECTED'].includes(row.status)" @click="edit(row)">编辑</el-button><el-button link type="success" :disabled="!['DRAFT','REJECTED'].includes(row.status)" @click="submit(row)">提交</el-button></template></el-table-column></el-table><TablePager v-model:page="page" v-model:size="size" :total="total" :disabled="loading" @change="load"/></el-card><el-dialog v-model="dialog" :title="editingId?'编辑工艺路线':'新增工艺路线'" width="1120px" top="4vh"><el-form label-position="top"><el-row :gutter="14"><el-col :span="6"><el-form-item label="路线编码" required><el-input v-model="form.routingCode" :disabled="Boolean(editingId)"/></el-form-item></el-col><el-col :span="6"><el-form-item label="路线名称" required><el-input v-model="form.routingName"/></el-form-item></el-col><el-col :span="6"><el-form-item label="产品" required><el-select v-model="form.productCode" filterable style="width:100%"><el-option v-for="p in products" :key="p.id" :label="`${p.productCode} · ${p.productName}`" :value="p.productCode"/></el-select></el-form-item></el-col><el-col :span="3"><el-form-item label="版本"><el-input v-model="form.routingVersion"/></el-form-item></el-col><el-col :span="3"><el-form-item label="生效日"><el-date-picker v-model="form.effectiveDate" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col></el-row><div class="ops-head"><b>工序明细</b><el-button size="small" @click="addOp">增加工序</el-button></div><el-table :data="form.operations" border max-height="370"><el-table-column label="顺序" width="85"><template #default="{row}"><el-input-number v-model="row.opSeq" :min="1" controls-position="right"/></template></el-table-column><el-table-column label="工序编码" width="130"><template #default="{row}"><el-input v-model="row.operationCode"/></template></el-table-column><el-table-column label="工序名称" width="140"><template #default="{row}"><el-input v-model="row.operationName"/></template></el-table-column><el-table-column label="工作中心" width="130"><template #default="{row}"><el-input v-model="row.workCenter"/></template></el-table-column><el-table-column label="准备(min)" width="115"><template #default="{row}"><el-input-number v-model="row.setupTimeMin" :min="0"/></template></el-table-column><el-table-column label="单件(min)" width="115"><template #default="{row}"><el-input-number v-model="row.runTimeMin" :min="0"/></template></el-table-column><el-table-column label="默认设备" width="130"><template #default="{row}"><el-input v-model="row.defaultEquipmentCode"/></template></el-table-column><el-table-column label="关键/检验" width="130"><template #default="{row}"><el-checkbox v-model="row.keyOperation">关键</el-checkbox><el-checkbox v-model="row.inspectionOp">检验</el-checkbox></template></el-table-column><el-table-column label="" width="60"><template #default="{$index}"><el-button link type="danger" @click="removeOp($index)">删除</el-button></template></el-table-column></el-table><el-form-item label="变更原因" style="margin-top:14px"><el-input v-model="form.changeReason"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog></section></template>
<style scoped>.biz-page{max-width:1480px;margin:0 auto}.page-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:17px}.page-head span{color:#3775d6;font-size:10px;font-weight:800;letter-spacing:1.4px}.page-head h1{margin:6px 0;color:#243d5d;font-size:25px}.page-head p{color:#8291a4;font-size:12px}.toolbar{display:flex;gap:9px;margin-bottom:14px}.toolbar .el-input{width:260px}.toolbar .el-select{width:160px}.ops-head{display:flex;justify-content:space-between;align-items:center;margin:5px 0 10px}</style>
